'use strict';

const DataClient = require('./client');
const DiskStore = require('./disk_store');
const VipDomainWithWeight = require('./vip_domain');
const APIClientBase = require('cluster-client').APIClientBase;

class AntvipClient extends APIClientBase {
  constructor(options) {
    super(Object.assign({}, options, { initMethod: '_init' }));
    this._isReady = false;
    this._resolvedVipDomains = new Map();
    this._diskStore = new DiskStore(options);

    this.ready(err => {
      this._isReady = !err;
    });
  }

  get DataClient() {
    return DataClient;
  }

  get clusterOptions() {
    return {
      name: `AntvipClient@${this.options.endpoint}`,
    };
  }

  /**
   * @property {boolean} AntvipClient#isReady
   */
  get isReady() {
    return this._isReady;
  }

  _formatKey(domainName) {
    return `apiclient#vipdomain#${domainName}`;
  }

  async _init() {
    await this._diskStore.ready();
  }

  _subscribeDomain(domainName) {
    // 防止重复订阅，这里只有 key 存在就不再订阅了:
    if (!this._resolvedVipDomains.has(domainName)) {
      const key = this._formatKey(domainName);
      this._client.subscribe(domainName, vipDomain => {
        if (vipDomain === null) {
          this.emit(key, null);
          return;
        }
        const weightVipDomain = new VipDomainWithWeight(vipDomain);
        this._resolvedVipDomains.set(vipDomain.name, weightVipDomain);
        this.emit(key, weightVipDomain);
      });
      this._resolvedVipDomains.set(domainName, null);
    }
  }

  async _getWeightVipDomain(domainName) {
    if (!this.isReady) {
      await this.ready();
    }
    let weightVipDomain = this._resolvedVipDomains.get(domainName);
    if (!weightVipDomain) {
      this._subscribeDomain(domainName);
      weightVipDomain = await this.await(this._formatKey(domainName));
    }
    return weightVipDomain;
  }

  async getRealServer(domainName) {
    const weightVipDomain = await this._getWeightVipDomain(domainName);
    return weightVipDomain && weightVipDomain.getRealServer();
  }

  async getRealServers(domainName) {
    const weightVipDomain = await this._getWeightVipDomain(domainName);
    return weightVipDomain && weightVipDomain.getAvailableRealServers();
  }

  async getAllRealServers(domainName) {
    const weightVipDomain = await this._getWeightVipDomain(domainName);
    return weightVipDomain && weightVipDomain.allRealServers;
  }

  /**
   * 订阅指定域名
   *
   * @param {String} domainName 域名
   * @param {Function} listener 监听函数
   */
  subscribe(domainName, listener) {
    // 要等 ready 后才能拿到域名列表
    if (!this.isReady) {
      this.ready().then(() => { this.subscribe(domainName, listener); });
      return;
    }

    this._subscribeDomain(domainName);
    const weightVipDomain = this._resolvedVipDomains.get(domainName);
    if (weightVipDomain) {
      setImmediate(() => { listener(weightVipDomain); });
    }
    this.on(this._formatKey(domainName), listener);
  }

  /**
   * 去订阅域名
   *
   * @param {String} domainName 域名
   * @param {Function} [listener] 监听函数
   */
  unSubscribe(domainName, listener) {
    const key = this._formatKey(domainName);
    if (listener) {
      this.removeListener(key, listener);
    } else {
      this.removeAllListeners(key);
    }
  }

  /**
   * 关闭客户端
   *
   * @return {Promise} defer
   */
  close() {
    return this._client.close();
  }
}

module.exports = AntvipClient;
